DROP TABLE IF EXISTS `biz_doc`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `biz_doc` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `doc_no` varchar(64) NOT NULL COMMENT '单号',
  `doc_type` smallint NOT NULL COMMENT '单据类型',
  `doc_type_name` varchar(32) NOT NULL DEFAULT '' COMMENT '单据类型名称（快照）',
  `biz_date` date NOT NULL,
  `partner_id` bigint unsigned NOT NULL DEFAULT '0',
  `partner_name` varchar(128) NOT NULL DEFAULT '' COMMENT '往来单位名称（快照）',
  `contact_phone` varchar(32) NOT NULL DEFAULT '' COMMENT '联系电话',
  `contact_address` varchar(255) NOT NULL DEFAULT '' COMMENT '联系地址',
  `warehouse_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '主仓库（调拨为出库仓）',
  `warehouse_name` varchar(64) NOT NULL DEFAULT '' COMMENT '发货仓库名称（快照）',
  `to_warehouse_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '调拨入库仓',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1待审 2已过账 9作废',
  `total_qty` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `total_amount` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `discount_amount` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `tax_amount` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `source_doc_no` varchar(64) DEFAULT NULL COMMENT '外部来源单号（幂等）',
  `ext` json DEFAULT NULL COMMENT '类型差异字段',
  `remark` varchar(255) NOT NULL DEFAULT '',
  `audited_at` datetime DEFAULT NULL,
  `audited_by` bigint unsigned NOT NULL DEFAULT '0',
  `posted_at` datetime DEFAULT NULL,
  `posted_by` bigint unsigned NOT NULL DEFAULT '0',
  `version` int NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint unsigned NOT NULL DEFAULT '0',
  `updated_by` bigint unsigned NOT NULL DEFAULT '0',
  `deleted_at` datetime DEFAULT NULL,
  `summary` varchar(255) NOT NULL DEFAULT '' COMMENT '摘要',
  `handler` varchar(64) NOT NULL DEFAULT '' COMMENT '经办人（用户名）',
  `creator_name` varchar(64) NOT NULL DEFAULT '' COMMENT '制单人（用户名）',
  `modifier_name` varchar(64) NOT NULL DEFAULT '' COMMENT '修改人（用户名）',
  `department` varchar(64) NOT NULL DEFAULT '' COMMENT '部门',
  `paid_amount` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '已收/已付金额',
  `print_count` int NOT NULL DEFAULT '0' COMMENT '打印次数',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_doc_no` (`doc_no`),
  UNIQUE KEY `uk_source` (`source_doc_no`),
  KEY `idx_type_date` (`doc_type`,`biz_date`),
  KEY `idx_partner` (`partner_id`,`biz_date`),
  KEY `idx_doc_no_prefix` (`doc_no`),
  KEY `idx_partner_name` (`partner_name`),
  KEY `idx_summary` (`summary`)
) ENGINE=InnoDB AUTO_INCREMENT=17804 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='业务单据头';
