--
-- Table structure for table `biz_doc_line`
--

DROP TABLE IF EXISTS `biz_doc_line`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `biz_doc_line` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `doc_id` bigint unsigned NOT NULL,
  `doc_no` varchar(64) NOT NULL DEFAULT '' COMMENT '单据编号（冗余快照）',
  `line_no` int NOT NULL,
  `item_id` bigint unsigned NOT NULL,
  `item_name` varchar(128) NOT NULL DEFAULT '' COMMENT '存货名称（快照）',
  `item_spec` varchar(255) NOT NULL DEFAULT '' COMMENT '规格型号（快照）',
  `item_color` varchar(64) NOT NULL DEFAULT '' COMMENT '颜色（快照）',
  `unit_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '录入单位',
  `unit_name` varchar(32) NOT NULL DEFAULT '' COMMENT '单位名称（快照）',
  `qty` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '录入单位数量',
  `base_qty` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '基本单位数量',
  `price` decimal(18,6) NOT NULL DEFAULT '0.000000' COMMENT '单价（不含税）',
  `amount` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `tax_rate` decimal(6,4) NOT NULL DEFAULT '0.0000',
  `tax_amount` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `warehouse_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '行仓库（覆盖头）',
  `location_id` bigint unsigned NOT NULL DEFAULT '0',
  `batch_no` varchar(64) NOT NULL DEFAULT '',
  `cost_price` decimal(18,6) NOT NULL DEFAULT '0.000000' COMMENT '出库成本（过账时回填）',
  `cost_amount` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `ext` json DEFAULT NULL,
  `remark` varchar(255) NOT NULL DEFAULT '',
  `summary` varchar(255) NOT NULL DEFAULT '' COMMENT '行摘要',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_doc_line` (`doc_id`,`line_no`),
  KEY `idx_item` (`item_id`),
  KEY `idx_doc` (`doc_id`),
  KEY `idx_item_name` (`item_name`),
  KEY `idx_line_doc_no` (`doc_no`)
) ENGINE=InnoDB AUTO_INCREMENT=44761 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='业务单据明细';
/*!40101 SET character_set_client = @saved_cs_client */;

