  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_item_unit` (`item_id`,`unit_id`),
  KEY `idx_unit` (`unit_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='存货多单位换算';
